//#region src/lib/site.ts
var SITE = {
	name: "IGRIS Tech",
	legalName: "IGRIS Tech",
	domain: "https://igristech.com",
	tagline: "We build what's next.",
	description: "IGRIS Tech builds digital products, software, websites, and intelligent solutions for individuals, brands, and businesses.",
	email: null,
	social: []
};
var NAV = [
	{
		label: "Services",
		to: "/services"
	},
	{
		label: "Work",
		to: "/work"
	},
	{
		label: "Ecosystem",
		to: "/ecosystem"
	},
	{
		label: "About",
		to: "/about"
	}
];
function absoluteUrl(path = "/") {
	if (path.startsWith("http")) return path;
	const normalized = path.startsWith("/") ? path : `/${path}`;
	return `${SITE.domain}${normalized}`;
}
//#endregion
//#region src/lib/seo.ts
function pageHead({ title, description, path = "/", noIndex }) {
	const url = absoluteUrl(path);
	return {
		meta: [
			{ title },
			{
				name: "description",
				content: description
			},
			{
				name: "theme-color",
				content: "#070708"
			},
			{
				name: "application-name",
				content: SITE.name
			},
			{
				property: "og:title",
				content: title
			},
			{
				property: "og:description",
				content: description
			},
			{
				property: "og:url",
				content: url
			},
			{
				property: "og:site_name",
				content: SITE.name
			},
			{
				name: "twitter:title",
				content: title
			},
			{
				name: "twitter:description",
				content: description
			},
			...noIndex ? [{
				name: "robots",
				content: "noindex, nofollow"
			}] : []
		],
		links: [{
			rel: "canonical",
			href: url
		}]
	};
}
function organizationJsonLd() {
	return {
		"@context": "https://schema.org",
		"@type": "Organization",
		name: SITE.name,
		url: SITE.domain,
		description: SITE.description,
		logo: `${SITE.domain}/brand/igris-mark.png`
	};
}
function websiteJsonLd() {
	return {
		"@context": "https://schema.org",
		"@type": "WebSite",
		name: SITE.name,
		url: SITE.domain,
		description: SITE.description
	};
}
function serviceJsonLd(name, description, url) {
	return {
		"@context": "https://schema.org",
		"@type": "Service",
		name,
		description,
		url,
		provider: {
			"@type": "Organization",
			name: SITE.name,
			url: SITE.domain
		}
	};
}
function breadcrumbJsonLd(items) {
	return {
		"@context": "https://schema.org",
		"@type": "BreadcrumbList",
		itemListElement: items.map((item, i) => ({
			"@type": "ListItem",
			position: i + 1,
			name: item.name,
			item: absoluteUrl(item.path)
		}))
	};
}
function creativeWorkJsonLd(input) {
	return {
		"@context": "https://schema.org",
		"@type": "CreativeWork",
		name: input.name,
		description: input.description,
		url: input.url,
		creator: {
			"@type": "Organization",
			name: SITE.name,
			url: SITE.domain
		},
		...input.dateCreated ? { dateCreated: input.dateCreated } : {}
	};
}
//#endregion
export { serviceJsonLd as a, SITE as c, pageHead as i, absoluteUrl as l, creativeWorkJsonLd as n, websiteJsonLd as o, organizationJsonLd as r, NAV as s, breadcrumbJsonLd as t };
